PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS work_mobile_sync_suppression(record_key TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS work_mobile_change_events(id INTEGER PRIMARY KEY AUTOINCREMENT,organization_id TEXT NOT NULL,collection_key TEXT NOT NULL,record_id TEXT NOT NULL,operation TEXT NOT NULL,payload_json TEXT);
CREATE TRIGGER work_mobile_change_apply AFTER INSERT ON work_mobile_change_events BEGIN
 INSERT INTO mobile_sync_record_versions(organization_id,module_key,collection_key,record_id,version,deleted,server_updated_at,last_device_id) VALUES(NEW.organization_id,'tasks-work',NEW.collection_key,NEW.record_id,1,NEW.operation='delete',CURRENT_TIMESTAMP,NULL) ON CONFLICT(organization_id,module_key,collection_key,record_id) DO UPDATE SET version=version+1,deleted=excluded.deleted,server_updated_at=CURRENT_TIMESTAMP,last_device_id=NULL;
 DELETE FROM mobile_sync_tombstones WHERE NEW.operation='upsert' AND organization_id=NEW.organization_id AND module_key='tasks-work' AND collection_key=NEW.collection_key AND record_id=NEW.record_id;
 INSERT INTO mobile_sync_tombstones(organization_id,module_key,collection_key,record_id,version,deleted_at,device_id) SELECT NEW.organization_id,'tasks-work',NEW.collection_key,NEW.record_id,version,CURRENT_TIMESTAMP,NULL FROM mobile_sync_record_versions WHERE NEW.operation='delete' AND organization_id=NEW.organization_id AND module_key='tasks-work' AND collection_key=NEW.collection_key AND record_id=NEW.record_id ON CONFLICT(organization_id,module_key,collection_key,record_id) DO UPDATE SET version=excluded.version,deleted_at=CURRENT_TIMESTAMP,device_id=NULL;
 INSERT INTO mobile_sync_changes(organization_id,module_key,collection_key,record_id,version,operation,payload_json,changed_by,device_id,changed_at) SELECT NEW.organization_id,'tasks-work',NEW.collection_key,NEW.record_id,version,NEW.operation,NEW.payload_json,NULL,NULL,CURRENT_TIMESTAMP FROM mobile_sync_record_versions WHERE organization_id=NEW.organization_id AND module_key='tasks-work' AND collection_key=NEW.collection_key AND record_id=NEW.record_id;
 DELETE FROM work_mobile_change_events WHERE id=NEW.id; END;
